#!/usr/bin/env python3
"""Generate documentation from the canonical prompt files used by every phase."""
from pathlib import Path
import html
ROOT=Path(__file__).resolve().parent.parent
DOCS=ROOT/'docs'
esc=html.escape
pages=[('index','Overview'),('clause-sop','Clause-SOP'),('event-sop','Event-SOP'),('sop-lng','Syntax'),('judge','Scoring'),('repair','Repair'),('symbolic','Symbolic-first'),('convention-audit','Convention audit')]
def code(text): return '<pre><code>'+esc(text)+'</code></pre>'
def table(headers,rows):
 return '<div class="table-wrap"><table><tr>'+''.join('<th>'+esc(str(x))+'</th>' for x in headers)+'</tr>'+''.join('<tr>'+''.join('<td>'+esc(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</table></div>'
def write(slug,title,lead,body):
 nav=''.join(f'<a href="{s}.html">{label}</a>' for s,label in pages)
 (DOCS/(slug+'.html')).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">LLM Formaliser</a><nav>{nav}</nav></header><main><h1>{esc(title)}</h1><p class="lead">{esc(lead)}</p>{body}</main></body></html>')
write('index','Two dialects, six workflows','One complete source file per task. Internal scoring anchors do not split model requests.',
 '<p>Each dialect has a baseline, a selective single-repair flow and a symbolic-first single-repair flow. All generation and repair phases include the identical canonical dialect text file. The shared judge prompt defines full-file equivalence and partial semantic coverage.</p>'+table(['Workflow','Steps'],[(f'formalise_{d}-judge','LLM generation → local CNL → judge → finish') for d in ['clause','event']]+[(f'formalise_{d}-symboliccheck-repair-judge','LLM generation → local checks → judge if eligible → repair if needed → local checks and rejudge → finish') for d in ['clause','event']]+[(f'symbolicformalise_{d}-symboliccheck-repair-judge','Local symbolic draft → diagnostics → conditional repair/judge → finish') for d in ['clause','event']])+
 '<p>Enqueue all tasks, then flush once. Compatible LLM phases batch together; local code and branching operate on each task’s own state. A wave waits for the current cohort before assembling subsequent batches. Accepted candidates skip repair. Model context and output budgets are resolved from pworker configuration; the 384000 output-token reservation is a ceiling, not a required output length.</p><p>Markdown uses phase headings and compact field headings such as <code>### tier:small</code>. Prompts include files through <code>${{lib/prompts/clause-sop.txt}}</code>; only the final input argument varies. Local phases contain explicit imports and code.</p><p><a href="../experiments/ten-whole-files.json">Ten complete source files</a> · <a href="../runs/experiment-035/coverage.html">Current six-flow experiment</a></p>')
write('sop-lng','Shared SOP syntax','Readable field names with explicit semantics and multiplicity.',code('@eventId TYPE key=value key=value ...')+
 table(['Convention','Meaning'],[('@id / $id','Unique declaration ID / explicit reference. IDs are unique across the entire file; forward references are allowed.'),('Scalar literals','Bare words, numbers, percentages, comparisons, dates and times are accepted. Quote whitespace and structural delimiters. Apostrophes inside bare words are literal. English thousands grouping such as 12,500_euro normalizes to 12500_euro; explicit bracket lists remain lists.'),('Quotes','Matching single or double quotes. Escape the quote delimiter inside its string. Numbers may be quoted or bare.'),('Lists','Use [a,b]. Clause participant groups have their own G declaration. No inline JSON objects.'),('Identical repeated scalar','Deduplicated with recorded normalization; no information is discarded.'),('List-valued fields','Repeated values collect in order. Event roles and time/place/manner/content, presuppositions and group members support repetition; Clause traits/flags/items/members support repetition.'),('Conflicting scalar','Reported for repair, never silently overwritten. Different tenses need separate events or an explicit alternative.'),('Missing references / duplicate IDs','Identical repeated declarations normalize idempotently. Conflicting records and missing references remain diagnostics; no meaning is invented.'),('Field vocabulary','tense for grammatical time; kind for record type/function; comparison for comparison relation. verb, status, subject, object, agent, theme, scope and other readable names replace ambiguous abbreviations.')])+
 '<p>The public vocabulary lives in <a href="../lib/sop-fields.mjs">sop-fields.mjs</a>; compact implementation keys are private converter details. Model-facing prompts, symbolic drafts and normalized SOP use readable names. Diagnostics collect independent problems; structure is validated after reliable parsing. Presentation fences can be removed losslessly. Source text is never silently rewritten to force an interpretation.</p>')
for slug,title in [('clause-sop','Clause-SOP'),('event-sop','Event-SOP')]:
 short=slug.removesuffix('-sop')
 write(slug,title,'The following is the exact canonical convention file shared by generation and repair.',
  '<p>Clause-SOP uses grammatical clauses, MOD modifiers and G participant groups. Event-SOP uses semantic roles, proposition graphs, explicit operators and quantifier scope. They share surface syntax but preserve their distinct semantics.</p>'+
  f'<p><a href="../lib/prompts/{slug}.txt">Canonical prompt</a> · <a href="../lib/{slug}.mjs">Converter</a> · <a href="../taskTypes/formalise_{short}-judge.md">Baseline task</a></p>'+
  code((ROOT/'lib/prompts'/(slug+'.txt')).read_text()))
write('judge','Semantic coverage and full equivalence','A file can be partly correct without being fully equivalent.',
 '<p>Each complete file receives deterministic sentence anchors with stable content-derived IDs and exact UTF-16 source offsets. The model receives the whole source, its complete reconstructed CNL and all anchors in one task input. Sentences are evaluation units, not independent tasks or claims that every sentence contains equally many propositions. Coreference and scope are judged in document context.</p>'+
 table(['Measure','Definition'],[('Preserved %','100 × preserved source units / evaluated units. A unit is preserved only if all its meaning survives.'),('Different / uncertain','Definite loss or change versus insufficient evidence; neither counts as preserved.'),('Assessed %','100 × evaluated units / all source units. Always displayed beside preservation.'),('Unassessable','Units of a file with no usable judgment, including structurally invalid conversions. Not scored as zero semantic correctness.'),('Bounds','Lower: preserved / all units. Upper: (preserved + uncertain + unassessable) / all units.'),('Additions','Unsupported candidate assertions are reported separately; full source coverage alone is insufficient. An omitted empty additions list is inferred only from an explicit source_entails_cnl=yes. Otherwise the addition count remains unknown.'),('Full equivalence','Both entailments, preserved force/ambiguity, every unit preserved, no additions and no mismatches.')])+
 '<p>Percentages describe sentence-level coverage, not a mathematically exact percentage of all meaning. Model judgments remain estimates. Invalid outputs do not disappear from denominators. Each unit ID must occur exactly once. Missing, duplicate or invented IDs prevent full equivalence; independently identifiable valid unit judgments remain usable, with affected units explicitly unassessable. No alignment is guessed from output order. Strict scoring of complex sentences remains conservative. The judge must not demand a pragmatic neg-raising reading or an exclusive unless reading without source support.</p>'+code((ROOT/'lib/prompts/judge.txt').read_text()))
write('repair','Conditional single-pass repair','Only candidates with concrete problems enter repair.',
 '<p>Local syntax/structure or numeric diagnostics skip the initial judge and become repair feedback. Valid candidates receive a judgment; semantic differences may trigger one repair. Success, uncertainty and malformed judge responses do not trigger speculative rewriting. The complete source and current SOP accompany all observed problems. Generation and repair use the identical dialect prompt file. After repair, local CNL is regenerated and only changed pairs require another judgment. Raw attempts, diagnostics and normalization evidence are preserved.</p><p>Cached judgments require an exact source/CNL/notation/anchor pair, the same selected model and the same judge context. Conflicting cached evidence is excluded. Pworker remains generic: these domain rules live in llmFormaliser.</p>')
write('symbolic','Symbolic-first drafts','Local preparation before any model repair.',
 '<p>The conservative symbolic parser recognizes a limited set of clauses, attitudes, modifiers and roles. Unsupported constructions remain UM source spans with diagnostics rather than invented semantic roles. Both exporters emit the same public field names used by their dialect prompts. Complete accepted drafts skip repair; incomplete drafts enter repair with their diagnostics. A whole file is never split into worker cases.</p>')
write('convention-audit','Convention and converter audit','Core corrections were frozen in experiment-033; additional lossless parser and scoring fixes are applied by local continuation experiment-035. Historical artifacts remain unchanged.',
 table(['Finding','Correction / remaining boundary'],[('Overloaded t','Separate tense, kind and comparison; use readable role and scope names throughout model-facing data.'),('Repeated fields rejected globally','Deduplicate identical scalar values; collect explicitly multivalued fields; retain genuine scalar conflicts.'),('Arbitrary literal whitelist','Accept unambiguous atoms such as 95%, >500_euro, dates and times; preserve structural delimiters.'),('All Clause questions rendered as whether','Explicit question kind and answer fields; prototype prompt examples regenerated with question/act annotations.'),('Suggestions rendered as orders','Explicit act=suggest and readable CNL force.'),('Event conditional premises rendered as facts','Conditional link endpoints are scoped content unless explicitly asserted; explicit contradictions stay visible.'),('Numeric false alarms','Preserve dates, normalize grouped numeric atoms and count entity labels such as room-12 only when their complete wording occurs in the source.'),('Whole-file binary score hides partial quality','Add exact sentence-anchor judgments, coverage, uncertainty, unassessable counts and unsupported additions.'),('Unreliable judge interpretations','Require source-grounded evidence; uncertainty instead of guessed readings; retain negation scope and non-exclusive unless unless context requires otherwise.'),('Malformed graphs','Undeclared references, duplicate IDs and contradictory scalar values remain visible; no fabricated repairs.')])+
 '<p>Validation tests include prototype round trips, both quote styles, literal punctuation, repeated roles/scalars, question kind, speech-act force, conditional scope, exact scoring-unit coverage and real pworker flows with fake LLMs. All six workflows retain one complete file per task.</p>')
print('Built canonical conventions, scoring and audit pages.')
